const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("bthr_rpc_response_topic", msg.rpcResponseTopic);
flow.set("bthr_write_result", msg.writeResult || null);

return msg;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 215,
    quantity: 3
};
return msg;

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    node.error("Invalid modbus response");
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "BatteryThresholdConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    shutdownCapacityPercent: data[0] || 0,   // 215
    restartCapacityPercent: data[1] || 0,    // 216
    lowBatteryCapacityPercent: data[2] || 0  // 217
};

const writeResult = flow.get("bthr_write_result");
const rpcResponseTopic = flow.get("bthr_rpc_response_topic");

flow.set("bthr_write_result", null);
flow.set("bthr_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

// Parse RPC params and build write queue
const params = msg.rpcParams || {};

const writes = [];

// Register 215: Shutdown Capacity %
if (params.shutdownCapacityPercent !== undefined) {
    writes.push({ register: 215, value: params.shutdownCapacityPercent, name: "Shutdown Capacity" });
}

// Register 216: Restart Capacity %
if (params.restartCapacityPercent !== undefined) {
    writes.push({ register: 216, value: params.restartCapacityPercent, name: "Restart Capacity" });
}

// Register 217: Low Battery Capacity %
if (params.lowBatteryCapacityPercent !== undefined) {
    writes.push({ register: 217, value: params.lowBatteryCapacityPercent, name: "Low Battery Capacity" });
}

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

// Store to GLOBAL context
global.set("bthr_write_queue", writes);
global.set("bthr_write_index", 0);
global.set("bthr_write_results", []);
global.set("bthr_write_rpc_topic", msg.rpcResponseTopic);

node.status({ fill: "blue", shape: "dot", text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("bthr_write_queue") || [];
const index = global.get("bthr_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("bthr_write_queue") || [];
let index = global.get("bthr_write_index") || 0;
const results = global.get("bthr_write_results") || [];

// Record success
const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("bthr_write_results", results);
}

// Move to next
index++;
global.set("bthr_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

// More writes?
if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done - go to read
const rpcTopic = global.get("bthr_write_rpc_topic");

global.set("bthr_write_queue", null);
global.set("bthr_write_index", null);
global.set("bthr_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
